   1 // Unit tests for vlinux's guest-RAM address math (runtime/linux/vlinux_mem.h).
   2 //
   3 // Why this file exists (ROADMAP_LINUX_RUNTIME.md U10c): mm.c, stack.c and
   4 // loader.c each turned the guest RAM SIZE into an absolute ADDRESS inline
   5 // (`mem_size - VLINUX_STACK_RESERVE`, `(char*) mem_size`, `mem_size -
   6 // HYBRID_V_SCRATCH_BYTES`), which is only correct while RAM starts at 0. That
   7 // assumption had no host-side test at all, and it is what made
   8 // `--mem-size 3G` fault before the app's first instruction (the stack landed
   9 // at 0xBF80_0000, an unmapped hole in the AE350 map). The math is now three
  10 // pure functions of (ram_base, mem_size), testable without a simulator.
  11 //
  12 // Same plain CHECK harness as infra_test.cpp (no doctest).
  13 #include <cstdint>
  14 
  15 #include "../runtime/linux/vlinux_mem.h"
  16 #include "hybrid/state_abi.h"
  17 #include "test_check.hpp"
  18 
  19 int main() {
  20   const uint64_t k1G = 1024ull * 1024 * 1024;
  21 
  22   // --- ram_base == 0: pins TODAY's behaviour, so the U10c extraction is
  23   //     provably behaviour-preserving (every caller still passes 0). ---
  24   {
  25     CHECK(vlinux_ram_top(0, k1G) == k1G);
  26     CHECK(vlinux_mmap_arena_top(0, k1G) == k1G - VLINUX_STACK_RESERVE);
  27     CHECK(vlinux_v_scratch_base(0, k1G) == k1G - HYBRID_V_SCRATCH_BYTES);
  28     // The historical 2 GiB-minus-scratch cap, spelled the old way.
  29     const uint64_t k2G = 2ull * 1024 * 1024 * 1024;
  30     CHECK(vlinux_ram_top(0, k2G - HYBRID_V_SCRATCH_BYTES)
  31           == k2G - HYBRID_V_SCRATCH_BYTES);
  32   }
  33 
  34   // --- ram_base != 0: the capability U10d's manifest field will switch on.
  35   //     0x8_00000000 is QEMU AE350's DRAM_ALIAS base, where the aliased low
  36   //     2 GiB runs contiguously into DRAM_EXT (hw/riscv/andes_ae350.c:131-132),
  37   //     so a >2 GiB guest gets ONE contiguous window. ---
  38   {
  39     const uint64_t kHigh = 0x800000000ull;
  40     const uint64_t k4G = 4ull * k1G;
  41     CHECK(vlinux_ram_top(kHigh, k4G) == 0x900000000ull);
  42     CHECK(vlinux_mmap_arena_top(kHigh, k4G)
  43           == 0x900000000ull - VLINUX_STACK_RESERVE);
  44     CHECK(vlinux_v_scratch_base(kHigh, k4G)
  45           == 0x900000000ull - HYBRID_V_SCRATCH_BYTES);
  46     // The 3G case that trap-stormed on 2026-07-29: with a zero base the stack
  47     // was built at 0xBF80_0000 (unmapped); with the high base it is in RAM.
  48     const uint64_t k3G = 3ull * k1G;
  49     CHECK(vlinux_mmap_arena_top(0, k3G) == 0xBF800000ull);  // the old bug
  50     CHECK(vlinux_mmap_arena_top(kHigh, k3G) == 0x8BF800000ull);
  51   }
  52 
  53   // --- the arena top must stay strictly below the scratch page, whatever the
  54   //     base: the V-transport page (HYBRID_V_SCRATCH_BYTES at the very top)
  55   //     must never be handed out by mmap. ---
  56   {
  57     const uint64_t bases[] = {0, 0x800000000ull};
  58     const uint64_t sizes[] = {128ull * 1024 * 1024, k1G, 4 * k1G, 6 * k1G};
  59     for (uint64_t base : bases) {
  60       for (uint64_t size : sizes) {
  61         CHECK(vlinux_mmap_arena_top(base, size)
  62               < vlinux_v_scratch_base(base, size));
  63         CHECK(vlinux_v_scratch_base(base, size) < vlinux_ram_top(base, size));
  64       }
  65     }
  66   }
  67 
  68   return andes_sim::test::report("vlinux-mem");
  69 }
=== vlinux_mem.h ===
   1 #ifndef VLINUX_MEM_H
   2 #define VLINUX_MEM_H
   3 
   4 #include <stdint.h>
   5 
   6 #include "hybrid/state_abi.h" /* HYBRID_V_SCRATCH_BYTES */
   7 
   8 /* Guest-RAM address math, in ONE place (ROADMAP_LINUX_RUNTIME.md U10c).
   9  *
  10  * Guest RAM is the half-open range [ram_base, ram_base + mem_size). mm.c,
  11  * stack.c and loader.c each used to derive their bounds from `mem_size` alone
  12  * -- correct only while ram_base == 0. These three functions take the base
  13  * explicitly so a guest placed anywhere (e.g. QEMU AE350's DRAM_ALIAS at
  14  * 0x8_00000000, where the aliased low 2 GiB runs contiguously into DRAM_EXT)
  15  * computes the same layout. Pure, header-only, host-testable:
  16  * driver/vlinux_mem_test.cpp.
  17  *
  18  * The layout, from the top of RAM down:
  19  *   ram_top          -- one past the last RAM byte; the initial stack is built
  20  *                       growing DOWN from here (stack.c)
  21  *   v_scratch_base   -- the hybrid V-register transport page, the top
  22  *                       HYBRID_V_SCRATCH_BYTES; never handed out (loader.c
  23  *                       rejects any PT_LOAD overlapping it)
  24  *   mmap_arena_top   -- ram_top - VLINUX_STACK_RESERVE: the mmap bump
  25  *                       allocator's ceiling, leaving the stack its headroom
  26  *                       above (mm.c)
  27  * VLINUX_STACK_RESERVE lives here rather than in stack.h because mm.c and
  28  * stack.c MUST agree on it (see the comment this replaces); one definition,
  29  * one header, no way for them to desynchronize.
  30  */
  31 #define VLINUX_STACK_RESERVE (8ull * 1024 * 1024)
  32 
  33 /* One past the last byte of guest RAM. */
  34 static inline uint64_t vlinux_ram_top(uint64_t ram_base, uint64_t mem_size)
  35 {
  36   return ram_base + mem_size;
  37 }
  38 
  39 /* The mmap bump allocator's ceiling: below the app stack's reservation. */
  40 static inline uint64_t vlinux_mmap_arena_top(uint64_t ram_base,
  41                                              uint64_t mem_size)
  42 {
  43   return vlinux_ram_top(ram_base, mem_size) - VLINUX_STACK_RESERVE;
  44 }
  45 
  46 /* First byte of the reserved hybrid V-transport scratch page. */
  47 static inline uint64_t vlinux_v_scratch_base(uint64_t ram_base,
  48                                              uint64_t mem_size)
  49 {
  50   return vlinux_ram_top(ram_base, mem_size) - HYBRID_V_SCRATCH_BYTES;
  51 }
  52 
  53 #endif /* VLINUX_MEM_H */

