  1 /* See mm.h. Two independent bump allocators (brk grows up from the app's
  2  * image end; mmap grows down from just below the app's stack) sharing
  3  * vlinux's own region bounds (_vlinux_base/_stack, vlinux.ld) as their
  4  * far walls -- the same linker symbols loader.c's overlap check uses, one
  5  * source of truth.
  6  */
  7 #include "mm.h"
  8 
  9 #include <string.h>
 10 
 11 #include "../htif_client.h"
 12 #include "linux_errno.h"
 13 #include "stack.h"
 14 
 15 #define PAGE_SIZE 4096ul
 16 
 17 #define PROT_WRITE 0x2      /* asm-generic/mman-common.h */
 18 #define MAP_SHARED 0x01     /* bits/mman-linux.h */
 19 #define MAP_PRIVATE 0x02
 20 #define MAP_ANONYMOUS 0x20  /* asm-generic/mman-common.h */
 21 
 22 extern char _vlinux_base[]; /* brk's ceiling */
 23 extern char _stack[];       /* mmap's floor (== vlinux's own end) */
 24 
 25 static uint64_t g_brk_start;   /* app image end: brk's floor */
 26 static uint64_t g_brk_cur;
 27 static uint64_t g_brk_ceiling; /* _vlinux_base */
 28 static uint64_t g_mmap_top;    /* next allocation lands just below this */
 29 static uint64_t g_mmap_floor;  /* _stack */
 30 static uint64_t g_mem_size;    /* the manifest's guest RAM size */
 31 
 32 void mm_init(uint64_t app_image_end, uint64_t ram_base, uint64_t mem_size)
 33 {
 34   g_brk_start = app_image_end;
 35   g_brk_cur = app_image_end;
 36   g_brk_ceiling = (uint64_t) (uintptr_t) _vlinux_base;
 37   g_mmap_floor = (uint64_t) (uintptr_t) _stack;
 38   g_mmap_top = vlinux_mmap_arena_top(ram_base, mem_size); /* below the stack */
 39   g_mem_size = mem_size;
 40 }
 41 
 42 uint64_t mm_total_ram(void) { return g_mem_size; }
 43 
 44 long sys_brk(unsigned long addr)
 45 {
 46   if (addr == 0) return (long) g_brk_cur;
 47   if (addr < g_brk_start || addr > g_brk_ceiling)
 48     return (long) g_brk_cur; /* Linux brk(2): failure returns the OLD break */
 49   g_brk_cur = addr;
 50   return (long) g_brk_cur;
 51 }
