 53 long sys_mmap(unsigned long addr, unsigned long length, long prot, long flags,
 54              long fd, long offset)
 55 {
 56   (void) addr;
 57   /* Every page is already RWX -- no MMU to restrict with -- EXCEPT prot
 58    * still decides whether a MAP_SHARED file mapping is safe to serve
 59    * below (a read-only one is; see there). */
 60   if (length == 0) return -EINVAL;
 61 
 62   const uint64_t need = ((uint64_t) length + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
 63   if (need > g_mmap_top - g_mmap_floor) return -ENOMEM;
 64   g_mmap_top -= need;
 65   void* base = (void*) (uintptr_t) g_mmap_top;
 66 
 67   if (flags & MAP_ANONYMOUS) {
 68     memset(base, 0, need);
 69     return (long) (uintptr_t) base;
 70   }
 71 
 72   /* File-backed (ROADMAP_LINUX_RUNTIME.md U7): read the file's
 73    * [offset, offset+length) range into the freshly-allocated arena
 74    * space, a private owned copy. MAP_SHARED without PROT_WRITE is
 75    * accepted too -- llama.cpp's own mmap loader (llama-mmap.cpp) uses
 76    * exactly this (MAP_SHARED, PROT_READ only) -- because a mapping
