 80    * here and is refused (-ENOSYS) rather than silently downgraded to a
 81    * private copy a caller might rely on staying shared. */
 82   if (flags & MAP_SHARED) {
 83     if (prot & PROT_WRITE) return -ENOSYS;
 84   } else if (!(flags & MAP_PRIVATE)) {
 85     return -ENOSYS;
 86   }
 87   const ssize_t n = htif_pread(fd, base, length, offset);
 88   if (n < 0) return n;
 89   if ((size_t) n < need) memset((char*) base + n, 0, need - (size_t) n);
 90   return (long) (uintptr_t) base;
 91 }
